import fs from 'node:fs';
const card = (title, content) => ({ title, content });
const section = (title, items) => ({ title, type: 'subcards', items });

function topic(formulas, concepts, questionTypes, proofs, errors, tips, takeaways) {
  return {
    sections: [
      section('Formula and skill map', [...formulas, card('Exam checks', tips.join('\n'))]),
      section('Core concepts and worked examples', concepts),
      section('Question types and solving approaches', questionTypes),
      section('Proofs and derivations', proofs),
      section('Common errors and how to avoid them', errors)
    ],
    upscNotes: [],
    keyTakeaways: takeaways,
    coverageAudit: {
      concepts: concepts.map((item) => item.title),
      questionTypes: questionTypes.map((item) => item.title),
      proofsAndDerivations: proofs.map((item) => item.title)
    }
  };
}

