for (const [slug, examples] of Object.entries(workedExamples)) {
  const sections = MATHEMATICS_STUDY[slug].sections;
  for (const [title, example] of Object.entries(examples)) {
    if (!example) continue;
    const item = sections.flatMap((group) => group.items).find((candidate) => candidate.title === title);
    if (!item) throw new Error(`Missing manual study card ${slug}: ${title}`);
    if (!/worked example/i.test(item.content)) item.content += example;
  }
}

