for (const [slug, sections] of Object.entries(additionalCoverage)) {
  for (const [indexText, additions] of Object.entries(sections)) {
    const index = Number(indexText);
    MATHEMATICS_STUDY[slug].sections[index].items.push(...additions);
    const auditKey = index === 1 ? 'concepts' : index === 2 ? 'questionTypes' : index === 3 ? 'proofsAndDerivations' : null;
    if (auditKey) MATHEMATICS_STUDY[slug].coverageAudit[auditKey].push(...additions.map((item) => item.title));
  }
}
